WHERE transfer_orders.status >= 0 AND transfer_orders.is_approve = 1

  AND transfer_orders.to_code LIKE CONCAT("%", #{filter.searchText}, "%")


  AND transfer_orders.order_date = #{filter.date}


  AND transfer_orders.to_type = #{filter.toType}


  AND transfer_orders.from_location_group_id = #{filter.fromWarehouseId}


  AND transfer_orders.to_location_group_id = #{filter.toWarehouseId}


  AND transfer_orders.status = #{filter.status}

mapper.select:
SELECT



ORDER BY


    ${filter.orderBy}


    transfer_orders.id DESC


LIMIT #{filter.page}, #{filter.rowsPerPage}

mapper.update:
UPDATE transfer_orders SET
  status = -1,
  modified = NOW(),
  modified_by = #{userId}
WHERE id = #{id};

UPDATE transfer_orders SET
     status = 3,
     is_process = 0,
     modified = NOW(),
     modified_by = #{userId}
WHERE id = #{request.id};
